using CameraFXSlots;using ExtensibleSaveFormat;using UnityEngine;using System.Text.Json;
using R=CameraFXSlots.CameraFXSlotsRunner;
using Object=UnityEngine.Object;
var results=new List<object>();int failed=0;
void Check(bool pass,string why){if(!pass)throw new Exception(why);}
void Reset(){R.Cleanup();R.SavedIndices=new();R.RestoredIndices=new();ExtendedSave.Incoming=null;ExtendedSave.Written=null;ExtendedSave.Reads=ExtendedSave.Writes=0;CameraFXSlotsPlugin.Logger.Lines.Clear();}
void Test(string name,Action action){try{Reset();action();results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;results.Add(new{name,passed=false,error=e.GetType().Name+": "+e.Message});Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Seed(){for(int i=0;i<20;i++){R.savedDoF[i]=Enumerable.Range(0,5).Select(x=>i*10f+x).ToArray();R.savedDoFEnabled[i]=(i%2)==0;R.savedFogFloats[i]=new[]{i+.1f,i+.2f,i+.3f};R.savedFogColors[i]=new[]{new Color(.1f,i,.3f,1),new Color(.7f,.6f,i,.4f)};R.savedFogEnabled[i]=(i%3)==0;}}
string Snapshot()=>JsonSerializer.Serialize(new{d=R.savedDoF,de=R.savedDoFEnabled,f=R.savedFogFloats,c=R.savedFogColors.Select(x=>x?.Select(v=>new[]{v.r,v.g,v.b,v.a})),fe=R.savedFogEnabled});
PluginData Payload(int index,float value=42,bool legacy=false){var p=new PluginData{version=3};for(int n=0;n<5;n++)p.data[(legacy?"slot":"dof_slot")+index+"_"+n]=value+n;p.data[(legacy?"slot":"dof_slot")+index+"_saved"]=true;p.data["dof_slot"+index+"_enabled"]=false;for(int n=0;n<3;n++)p.data["fog_slot"+index+"_f"+n]=value+n;p.data["fog_slot"+index+"_saved"]=true;p.data["fog_slot"+index+"_enabled"]=false;for(int n=0;n<2;n++)foreach(var channel in new[]{"r","g","b","a"})p.data["fog_slot"+index+"_c"+n+"_"+channel]=value+n;return p;}
void ImportKeeps(PluginData incoming){Seed();var before=Snapshot();var first=R.savedDoF[0];var last=R.savedFogColors[19];R.HookExtendedSaveEvents();ExtendedSave.Incoming=incoming;ExtendedSave.Import();Check(Snapshot()==before&&ReferenceEquals(first,R.savedDoF[0])&&ReferenceEquals(last,R.savedFogColors[19]),"import replaced current camera FX slots");}
Test("null import preserves all20 slots and identities",()=>ImportKeeps(null));
Test("empty plugin data import preserves all20 slots",()=>ImportKeeps(new PluginData()));
Test("unrelated keys import preserves current effects",()=>{var p=new PluginData();p.data["unrelated"]="value";ImportKeeps(p);});
Test("valid source FX import keeps current camera ownership",()=>ImportKeeps(Payload(0)));
Test("legacy valid source FX import keeps current slots",()=>ImportKeeps(Payload(19,88,true)));
Test("malformed import marker cannot throw or erase slots",()=>{var p=new PluginData();p.data["dof_slot0_saved"]="bad";ImportKeeps(p);});
Test("incomplete imported slot does not erase existing data",()=>{var p=new PluginData();p.data["dof_slot1_saved"]=true;ImportKeeps(p);});
Test("null inner import dictionary keeps current slots",()=>ImportKeeps(new PluginData{data=null}));
Test("import into empty camera bank does not add unrelated slots",()=>{R.HookExtendedSaveEvents();ExtendedSave.Incoming=Payload(3);ExtendedSave.Import();Check(R.savedDoF.All(x=>x==null)&&R.savedFogFloats.All(x=>x==null),"import populated FX without native camera slots");});
Test("import route does not read or write extended data",()=>{R.HookExtendedSaveEvents();ExtendedSave.Incoming=Payload(0);ExtendedSave.Import();Check(ExtendedSave.Reads==0&&ExtendedSave.Writes==0,"import reads foreign data");});
Test("normal load replaces20slots and reads supplied data",()=>{Seed();R.HookExtendedSaveEvents();ExtendedSave.Incoming=Payload(7);ExtendedSave.Load();Check(R.savedDoF[7][0]==42&&!R.savedDoFEnabled[7]&&R.savedFogFloats[7][0]==42&&!R.savedFogEnabled[7]&&R.savedDoF.Where((_,i)=>i!=7).All(x=>x==null),"normal load changed");});
Test("normal load without data clears all existing slots",()=>{Seed();R.HookExtendedSaveEvents();ExtendedSave.Load();Check(R.savedDoF.All(x=>x==null)&&R.savedFogColors.All(x=>x==null)&&R.savedDoFEnabled.All(x=>!x)&&R.savedFogEnabled.All(x=>!x),"empty load did not clear");});
Test("normal legacy dof load remains compatible",()=>{R.OnSceneLoad("empty");ExtendedSave.Incoming=Payload(19,77,true);R.OnSceneLoad("legacy");Check(R.savedDoF[19][0]==77,"legacy decoder changed");});
Test("normal numeric float double int coercion retained",()=>{var p=Payload(2);p.data["dof_slot2_0"]=6;p.data["dof_slot2_1"]=2.5d;ExtendedSave.Incoming=p;R.OnSceneLoad("numeric");Check(R.savedDoF[2][0]==6&&R.savedDoF[2][1]==2.5f,"numeric conversion changed");});
Test("normal malformed property skips only invalid slot",()=>{var p=Payload(0);p.data.Remove("dof_slot0_2");ExtendedSave.Incoming=p;R.OnSceneLoad("invalid");Check(R.savedDoF[0]==null&&R.savedFogFloats[0]!=null,"normal invalid slot policy changed");});
Test("original save format and slot counts retained",()=>{Seed();var before=Snapshot();R.HookExtendedSaveEvents();ExtendedSave.Save();Check(ExtendedSave.Writes==1&&ExtendedSave.Written.version==3&&(int)ExtendedSave.Written.data["dofSlotCount"]==20&&(int)ExtendedSave.Written.data["fogSlotCount"]==20&&Snapshot()==before,"save format/state changed");});
Test("actual save-load roundtrip retains all effects",()=>{Seed();var before=Snapshot();R.HookExtendedSaveEvents();ExtendedSave.Save();ExtendedSave.Incoming=ExtendedSave.Written;ExtendedSave.Load();Check(Snapshot()==before,"roundtrip lost effect values");});
Test("repeated hook creates only one load/save subscriber",()=>{R.HookExtendedSaveEvents();R.HookExtendedSaveEvents();Check(ExtendedSave.SavedCount==1&&ExtendedSave.LoadedCount==1,"duplicate subscriptions");});
Test("import has no destructive subscriber",()=>{R.HookExtendedSaveEvents();Check(ExtendedSave.ImportedCount==0,"import still linked to OnSceneLoad");});
Test("repeated unhook clears original lifecycle handlers",()=>{R.HookExtendedSaveEvents();R.UnhookExtendedSaveEvents();R.UnhookExtendedSaveEvents();Check(ExtendedSave.SavedCount==0&&ExtendedSave.LoadedCount==0&&ExtendedSave.ImportedCount==0&&!R.eventsHooked,"event handlers leak");});
Test("cleanup destroys owned buttons and clears20 slots",()=>{Seed();var owned=new GameObject();R.addedButtons.Add(owned);R.HookExtendedSaveEvents();R.Cleanup();Check(owned.Destroyed&&R.addedButtons.Count==0&&R.savedDoF.All(x=>x==null)&&R.savedFogColors.All(x=>x==null)&&!R.eventsHooked&&ExtendedSave.LoadedCount==0,"cleanup changed");});
Test("cleanup followed by startup rehooks exactly once",()=>{R.HookExtendedSaveEvents();R.Cleanup();R.HookExtendedSaveEvents();R.HookExtendedSaveEvents();Check(ExtendedSave.LoadedCount==1&&ExtendedSave.SavedCount==1&&ExtendedSave.ImportedCount==0,"lifecycle rehook incorrect");});
Test("detached events cannot mutate preserved data",()=>{Seed();var before=Snapshot();R.HookExtendedSaveEvents();R.UnhookExtendedSaveEvents();ExtendedSave.Incoming=Payload(1);ExtendedSave.Load();ExtendedSave.Import();ExtendedSave.Save();Check(Snapshot()==before&&ExtendedSave.Reads==0&&ExtendedSave.Writes==0,"detached callback still ran");});
void Child(Transform parent,GameObject child){child.transform.parent=parent;parent.Children.Add(child.transform);}
Transform Slot(Transform content,int i){var go=new GameObject(i.ToString("00"));Child(content,go);foreach(string name in new[]{"Button Save","Button Load"}){var b=new GameObject(name);b.AddComponent<UnityEngine.UI.Image>();b.AddComponent<UnityEngine.UI.Button>();Child(go.transform,b);}return go.transform;}
(R runner,Transform content) Setup(int count){GameObject.Registry.Clear();Singleton<Studio.Studio>.Instance=new();var scroll=new GameObject("Scroll");scroll.transform.sizeDelta=new(800,51);var viewport=new GameObject("Viewport");Child(scroll.transform,viewport);var content=new GameObject("Content");content.transform.sizeDelta=new(900,310);Child(viewport.transform,content);GameObject.Registry["StudioScene/Canvas System Menu/02_Camera/Scroll"]=scroll;GameObject.Registry["StudioScene/Canvas System Menu/02_Camera/Scroll/Viewport/Content"]=content;for(int i=0;i<count;i++)Slot(content.transform,i);return(new R(),content.transform);}
void Tick(R runner){Time.realtimeSinceStartup+=1;runner.Update();}
bool HasFx(Transform slot)=>slot.Find("Button FX Save")!=null;
Test("initial ten slots created exactly once",()=>{var(r,c)=Setup(10);Tick(r);Tick(r);Check(c.Children.All(HasFx)&&R.addedButtons.Count==10,"initial slot count");});
Test("growing camera bank adds only new slots",()=>{var(r,c)=Setup(10);Tick(r);Slot(c,10);Slot(c,11);Tick(r);Check(c.Children.All(HasFx)&&R.addedButtons.Count==12,"growth failed");});
Test("same-count Moar replacement rebinds new slot objects",()=>{var(r,c)=Setup(12);Tick(r);for(int i=11;i>=10;i--)Object.Destroy(c.GetChild(i).gameObject);Slot(c,10);Slot(c,11);Tick(r);Check(HasFx(c.GetChild(10))&&HasFx(c.GetChild(11)),"same-count replacement ignored");});
Test("shrink then regrow below historical maximum rebinds",()=>{var(r,c)=Setup(12);Tick(r);for(int i=11;i>=10;i--)Object.Destroy(c.GetChild(i).gameObject);Tick(r);Slot(c,10);Slot(c,11);Tick(r);Check(HasFx(c.GetChild(10))&&HasFx(c.GetChild(11)),"regrown slots ignored");});
Test("native load event replacement gains one owned callback",()=>{var(r,c)=Setup(10);Tick(r);var b=c.GetChild(0).Find("Button Load").GetComponent<UnityEngine.UI.Button>();b.onClick=new();Tick(r);Check(b.onClick.Listeners.Count==1,"new event not hooked");});
Test("cleanup removes only own native load callback",()=>{var(r,c)=Setup(10);var b=c.GetChild(0).Find("Button Load").GetComponent<UnityEngine.UI.Button>();int external=0;UnityEngine.Events.UnityAction action=()=>external++;b.onClick.AddListener(action);Tick(r);R.Cleanup();b.onClick.Invoke();Check(external==1&&b.onClick.Listeners.Count==1,"owned load callback leaked or foreign deleted");});
Test("cleanup restores captured nondefault layout",()=>{var(r,c)=Setup(10);Tick(r);R.Cleanup();Check(((RectTransform)c).sizeDelta.y==310&&GameObject.Registry["StudioScene/Canvas System Menu/02_Camera/Scroll"].transform.sizeDelta.y==51,"fixed48/300 layout overwrote original");});
Test("cleanup keeps externally changed layout",()=>{var(r,c)=Setup(10);Tick(r);((RectTransform)c).sizeDelta=new(900,555);R.Cleanup();Check(((RectTransform)c).sizeDelta.y==555,"foreign layout overwritten");});
Test("replacement native load Button gets one own listener",()=>{var(r,c)=Setup(10);Tick(r);var old=c.GetChild(0).Find("Button Load");var oldButton=old.GetComponent<UnityEngine.UI.Button>();Object.Destroy(old.gameObject);var replacement=new GameObject("Button Load");replacement.AddComponent<UnityEngine.UI.Image>();var button=replacement.AddComponent<UnityEngine.UI.Button>();Child(c.GetChild(0),replacement);Tick(r);Check(button.onClick.Listeners.Count==1&&oldButton.onClick.Listeners.Count==0,"replaced button binding incorrect");});
Test("whole parent replacement detaches still-alive previous nodes",()=>{var(r,c)=Setup(10);Tick(r);var old=c.GetChild(0).Find("Button Load").GetComponent<UnityEngine.UI.Button>();var(_,replacement)=Setup(10);Tick(r);Check(old.onClick.Listeners.Count==0&&replacement.Children.All(HasFx),"old parent listeners kept or new parent ignored");});
Test("external callback survives repeated reconciliation",()=>{var(r,c)=Setup(10);Tick(r);var b=c.GetChild(0).Find("Button Load").GetComponent<UnityEngine.UI.Button>();int external=0;b.onClick.AddListener(()=>external++);for(int i=0;i<10;i++)Tick(r);Check(b.onClick.Listeners.Count==2&&R.addedButtons.Count==10,"duplicate or lost listener");R.Cleanup();b.onClick.Invoke();Check(external==1&&b.onClick.Listeners.Count==1,"cleanup touched external callback");});
Test("destroyed FX object rebuilt without stale image ownership",()=>{var(r,c)=Setup(10);Tick(r);var old=R.fxButtonImages[0];Object.Destroy(c.GetChild(0).Find("Button FX Save").gameObject);Tick(r);Check(HasFx(c.GetChild(0))&&!ReferenceEquals(old,R.fxButtonImages[0])&&R.addedButtons.Count==10,"destroyed FX not replaced cleanly");});
Test("slot count capped at20 with complete cleanup",()=>{var(r,c)=Setup(23);Tick(r);Check(R.addedButtons.Count==20&&c.Children.Take(20).All(HasFx)&&c.Children.Skip(20).All(x=>!HasFx(x)),"20slot bound changed");R.Cleanup();Check(R.addedButtons.Count==0&&R.fxButtonImages.All(x=>x==null),"capped cleanup incomplete");});
Test("poll is throttled but eventually handles new identities",()=>{var(r,c)=Setup(10);Tick(r);Object.Destroy(c.GetChild(9).gameObject);Slot(c,9);r.Update();Check(!HasFx(c.GetChild(9)),"unthrottled same-frame reconcile");Time.realtimeSinceStartup+=.3f;r.Update();Check(HasFx(c.GetChild(9)),"delayed reconcile never catches up");});
Test("destroyed parent then missing parent releases owned bindings",()=>{var(r,c)=Setup(10);Tick(r);var b=c.GetChild(0).Find("Button Load").GetComponent<UnityEngine.UI.Button>();Object.Destroy(c.gameObject);GameObject.Registry.Clear();Tick(r);Tick(r);Check(b.onClick.Listeners.Count==0&&R.addedButtons.Count==0&&R.fxButtonImages.All(x=>ReferenceEquals(x,null)),"destroyed parent matched Unity null without releasing ownership");});
Test("incomplete save template rejected without leaking FX clone",()=>{var(r,c)=Setup(10);c.GetChild(0).Find("Button Save").gameObject.Components.Remove(typeof(UnityEngine.UI.Image));Tick(r);Tick(r);Check(!HasFx(c.GetChild(0))&&R.addedButtons.Count==9,"partial template leaked clone");});
Test("cloned own FX marker is replaced without duplicate buttons",()=>{var(r,c)=Setup(10);Tick(r);var source=c.GetChild(0).Find("Button FX Save").gameObject;var newSlot=Slot(c,10);var inherited=new GameObject("Button FX Save");inherited.AddComponent<UnityEngine.UI.Image>();var oldButton=inherited.AddComponent<UnityEngine.UI.Button>();oldButton.onClick.Listeners.AddRange(source.GetComponent<UnityEngine.UI.Button>().onClick.Listeners);Child(newSlot,inherited);var marker=source.Components.Values.FirstOrDefault(x=>x.GetType().FullName=="CameraFXSlotsRepair.FxOwnership");if(marker!=null){var copy=(Component)Activator.CreateInstance(marker.GetType());copy.gameObject=inherited;marker.GetType().GetField("Owner").SetValue(copy,r);inherited.Components.Add(marker.GetType(),copy);}Tick(r);Check(newSlot.Children.Count(x=>x.gameObject.name=="Button FX Save")==1&&inherited.Destroyed&&!inherited.activeSelf,"template FX clone duplicated instead of replacing owned inherited button");R.SavedIndices.Clear();newSlot.Find("Button FX Save").GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Check(R.SavedIndices.SequenceEqual(new[]{10,10}),"new slot kept copied slot0 closure");R.SavedIndices.Clear();source.GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Check(R.SavedIndices.SequenceEqual(new[]{0,0}),"original slot callback changed");});
Test("unmarked same-name foreign button survives reconcile",()=>{var(r,c)=Setup(10);var foreign=new GameObject("Button FX Save");Child(c.GetChild(0),foreign);Tick(r);Check(!foreign.Destroyed&&c.GetChild(0).Children.Count(x=>x.gameObject.name=="Button FX Save")==2,"unmarked foreign control was deleted");});
R.Cleanup();var report=new{checks=results.Count,failures=failed,results,scope="Actual original/candidate managed methods including event/data/UI construction with synthetic Unity/ExtendedSave collaborators. No real scene IO, material rendering or game execution."};File.WriteAllText(args[0],JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"checks={results.Count} failures={failed}");return failed==0?0:1;
